WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_text_multi_para'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多段文字', 'kp-xingce-data-text-multi-para', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多段文字"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "由若干个段落组成的材料，结构相对清晰，首句定位法是核心。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "材料被分成了 3 到 5 段。这种结构其实比单段长文更友好，因为命题人已经帮你切分好了层级。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "每一段的首句通常是中心句（总起句）。必须建立“脑内目录”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到多段文字] --> B[花 15 秒扫视每一段的第一句话]\nB --> C[提炼出每段的主体]\nC --> D[段1: 农业; 段2: 工业; 段3: 服务业]\nD --> E[看第一道题干, 问的是什么?]\nE -- 问工业 --> F[眼睛只看第 2 段, 其他段落全部屏蔽]\nF --> G[在第 2 段内精准找数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【场景】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 题目问：2023年第三产业中，住宿和餐饮业的增加值是多少？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "回忆目录：第一段讲总GDP，第二段讲一二产业，第三段首句是“第三产业持续恢复...”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "空降定位：直接跳过前两段，直奔第三段内部扫读。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "寻找细节：在第三段中寻找“住宿和餐饮业”这几个字，提取其后面的数值。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "漫无目的地从头找：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目问的是最后一段的数据，你非要从第一段第一行开始按顺序往下扫。等扫到最后一段，半分钟已经没了。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "练习给段落起小标题的能力。段落旁边可以写上“农”、“工”、“进出口”等单字作为提示。"}]}]}$$ AS jsonb), NULL, '多段文字的核心读题与防坑技巧。', category_node.id, CAST('["资料分析", "多段文字"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_text_multi_para", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
